static void i2c_rtio_exec(struct rtio_iodev_sqe *sqe)
{
	struct i2c_rtio_data *data = sqe->iodev->data;
	const struct i2c_rtio_config *config = sqe->iodev->config;
	struct i2c_msg msg;
	uint32_t len;
	int ret;

	if (sqe->op == RTIO_OP_RX) {
		msg.flags = I2C_MSG_READ;
		ret = rtio_sqe_rx_buf(sqe, 1, UINT32_MAX, &msg.buf, &len);
	} else {
		msg.flags = I2C_MSG_WRITE;
		ret = rtio_sqe_tx_buf(sqe, 1, UINT32_MAX, (const uint8_t **)&msg.buf, &len);
	}

	if (ret != 0) {
		rtio_iodev_sqe_err(sqe, ret);
		return;
	}

	msg.len = len;

	ret = i2c_transfer(config->i2c_dev, &msg, 1, data->addr);
	if (ret != 0) {
		rtio_iodev_sqe_err(sqe, ret);
		return;
	}

	rtio_iodev_sqe_ok(sqe, 0);
}
