static void i2c_rtio_exec(struct rtio_iodev_sqe *sqe)
{
	struct i2c_rtio_data *data = sqe->iodev->data;
	const struct i2c_rtio_config *config = sqe->iodev->config;
	struct i2c_rtio_msg *i2c_rtio_msg;
	uint32_t len;
	int ret;

	i2c_rtio_msg = k_malloc(sizeof(*i2c_rtio_msg));
	if (i2c_rtio_msg == NULL) {
		rtio_iodev_sqe_err(sqe, -ENOMEM);
		return;
	}

	i2c_rtio_msg->sqe = sqe;

	if (sqe->op == RTIO_OP_RX) {
		i2c_rtio_msg->msg.flags = I2C_MSG_READ;
		ret = rtio_sqe_rx_buf(sqe, 1, UINT32_MAX, &i2c_rtio_msg->msg.buf, &len);
	} else {
		i2c_rtio_msg->msg.flags = I2C_MSG_WRITE;
		ret = rtio_sqe_tx_buf(sqe, 1, UINT32_MAX,
				      (const uint8_t **)&i2c_rtio_msg->msg.buf, &len);
	}

	if (ret != 0) {
		rtio_iodev_sqe_err(sqe, ret);
		k_free(i2c_rtio_msg);
		return;
	}

	i2c_rtio_msg->msg.len = len;

	ret = i2c_transfer_cb(config->i2c_dev, &i2c_rtio_msg->msg, 1, data->addr, i2c_rtio_cb,
			      i2c_rtio_msg);
	if (ret != 0) {
		rtio_iodev_sqe_err(sqe, ret);
		k_free(i2c_rtio_msg);
		return;
	}
}
